// @ts-nocheck
/**
 * T4A (Canadian contractor) yearly summary generator — Phase 2.
 *
 * Not a CRA e-file. The company accountant will take the CSV generated by
 * `/api/admin/driver-tax` and prepare the official T4A slips offline.
 *
 * Rules we apply:
 *   totalPaid = sum(DriverEarning.driverNet where status=PAID AND paidAt∈[year]) +
 *               sum(DriverAdjustment.amount where createdAt∈[year])
 *
 * `year` is a calendar year in America/Toronto — matches how the driver would file
 * personal taxes in Ontario. We bracket the year via a UTC-midnight proxy that is
 * correct through the whole year (the small DST ambiguity at Jan 1 00:00 does not
 * affect totals, every payout gets counted exactly once).
 */

import prisma from "@/lib/prisma";
import { roundMoney, writeAudit } from "@/lib/driver-pay";

/**
 * Returns `[start, end)` as UTC Date objects bracketing the given Toronto calendar year.
 * Jan 1 00:00 Toronto EST = Jan 1 05:00 UTC (standard time — year boundary is always
 * in EST, not EDT, so UTC+5 is exact for Jan 1).
 */
export function torontoYearRange(year: number): { start: Date; end: Date } {
  const start = new Date(Date.UTC(year, 0, 1, 5, 0, 0));
  const end = new Date(Date.UTC(year + 1, 0, 1, 5, 0, 0));
  return { start, end };
}

export type TaxYearRow = {
  driverId: string;
  driverCode: string;
  driverName: string;
  driverEmail: string;
  year: number;
  totalPaid: number;
  earningsPaid: number;
  adjustmentsTotal: number;
  earningsCount: number;
  adjustmentsCount: number;
  generatedAt: string;
};

/** Compute (don't persist) the tax summary for every active driver for the given year. */
export async function computeTaxYearSummaries(year: number): Promise<TaxYearRow[]> {
  const { start, end } = torontoYearRange(year);

  const drivers = await prisma.driver.findMany({
    orderBy: { name: "asc" },
    select: { id: true, driverId: true, name: true, email: true },
  });

  const results: TaxYearRow[] = [];
  for (const d of drivers) {
    const [earnAgg, adjAgg] = await Promise.all([
      prisma.driverEarning.aggregate({
        where: {
          driverId: d.id,
          status: "PAID",
          payout: { paidAt: { gte: start, lt: end } },
        },
        _sum: { driverNet: true },
        _count: true,
      }),
      prisma.driverAdjustment.aggregate({
        where: {
          driverId: d.id,
          createdAt: { gte: start, lt: end },
        },
        _sum: { amount: true },
        _count: true,
      }),
    ]);

    const earningsPaid = roundMoney(earnAgg._sum.driverNet || 0);
    const adjustmentsTotal = roundMoney(adjAgg._sum.amount || 0);
    const totalPaid = roundMoney(earningsPaid + adjustmentsTotal);

    if (earningsPaid === 0 && adjustmentsTotal === 0 && earnAgg._count === 0 && adjAgg._count === 0) {
      continue; // skip drivers with zero activity for the year
    }

    results.push({
      driverId: d.id,
      driverCode: d.driverId,
      driverName: d.name,
      driverEmail: d.email,
      year,
      totalPaid,
      earningsPaid,
      adjustmentsTotal,
      earningsCount: earnAgg._count || 0,
      adjustmentsCount: adjAgg._count || 0,
      generatedAt: new Date().toISOString(),
    });
  }

  return results;
}

/** Compute + persist (upsert) the summary rows, writing audit entries. */
export async function generateAndPersistTaxYear(
  year: number,
  actor: string = "admin"
): Promise<{ generated: number; rows: TaxYearRow[] }> {
  const rows = await computeTaxYearSummaries(year);
  const now = new Date();

  for (const r of rows) {
    await prisma.driverTaxYearSummary.upsert({
      where: { driverId_year: { driverId: r.driverId, year } },
      update: {
        totalPaid: r.totalPaid,
        earningsPaid: r.earningsPaid,
        adjustmentsTotal: r.adjustmentsTotal,
        earningsCount: r.earningsCount,
        adjustmentsCount: r.adjustmentsCount,
        generatedAt: now,
      },
      create: {
        driverId: r.driverId,
        year,
        totalPaid: r.totalPaid,
        earningsPaid: r.earningsPaid,
        adjustmentsTotal: r.adjustmentsTotal,
        earningsCount: r.earningsCount,
        adjustmentsCount: r.adjustmentsCount,
        generatedAt: now,
      },
    });
  }

  await writeAudit({
    action: "tax_year_generated",
    entityType: "TAX",
    entityId: `year:${year}`,
    details: { year, count: rows.length },
    actor,
  });

  return { generated: rows.length, rows };
}

/** Convert rows to a T4A-ready CSV string. */
export function toCsv(rows: TaxYearRow[], year: number): string {
  const header = [
    "Driver Code",
    "Driver Name",
    "Driver Email",
    "Year (America/Toronto)",
    "Earnings Paid (CAD)",
    "Earnings Count",
    "Adjustments Total (CAD)",
    "Adjustments Count",
    "Total Paid (CAD)",
    "Generated (UTC)",
  ].join(",");

  const escape = (v: unknown) => {
    const s = String(v ?? "");
    if (/[",\n]/.test(s)) return `"${s.replace(/"/g, '""')}"`;
    return s;
  };

  const body = rows
    .map((r) =>
      [
        escape(r.driverCode),
        escape(r.driverName),
        escape(r.driverEmail),
        year,
        r.earningsPaid.toFixed(2),
        r.earningsCount,
        r.adjustmentsTotal.toFixed(2),
        r.adjustmentsCount,
        r.totalPaid.toFixed(2),
        r.generatedAt,
      ].join(",")
    )
    .join("\n");

  return `${header}\n${body}\n`;
}
